static final ScopedValue<String> TENANT = ScopedValue.newInstance();   // final in JDK 25

Statement statement(Request req) throws Exception {
    return ScopedValue.where(TENANT, req.tenant()).call(() -> {          // bound for this call
        try (var scope = StructuredTaskScope.open()) {                   // preview in JDK 25
            Subtask<Customer> customer = scope.fork(() -> crm.find(req.customerId()));
            Subtask<Balance> balance = scope.fork(() -> ledger.balance(ledgerKey(req.account())));
            scope.join();
            return new Statement(customer.get(), balance.get());
        }
    });
}

static String ledgerKey(String account) {
    return TENANT.get() + ":" + account;   // the fork reads the parent's binding
}

