// the coroutine carries the context, not the thread
class Tenant(val id: String) : AbstractCoroutineContextElement(Tenant) {
    companion object Key : CoroutineContext.Key<Tenant>
}

suspend fun statement(req: Request): Statement = withContext(Tenant(req.tenant)) {   // bound for this block
    val customer = async { crm.find(req.customerId) }
    val balance = async { ledger.balance(ledgerKey(req.account)) }      // children inherit the context
    Statement(customer.await(), balance.await())
}

suspend fun ledgerKey(account: String): String =
    (currentCoroutineContext()[Tenant]?.id ?: error("no tenant")) + ":" + account

