Quote quote(String id) throws InterruptedException {
    try (var scope = StructuredTaskScope.open()) {                  // default: fail on the first failure
        Subtask<Customer> customer = scope.fork(() -> crm.find(id));
        Subtask<Limit> limit = scope.fork(() -> limits.check(id));
        scope.join();                                               // throws if a subtask failed
        return new Quote(customer.get(), limit.get());              // get() only after join()
    }                                                               // close() waits for every subtask
}

// a caller on JDK 25
try {
    return quote(id);
} catch (StructuredTaskScope.FailedException e) {     // unchecked; the cause is the subtask's exception
    throw new QuoteUnavailableException(e.getCause());
}
// on JDK 27 and later, join() throws the checked ExecutionException instead:
// } catch (ExecutionException e) { throw new QuoteUnavailableException(e.getCause()); }

